-- 014_seed_2016_items.sql
-- Seed 2016 unique items and their batches from Marg.csv & HSN.XLS

DO $$
DECLARE
  org_rec RECORD;
  v_item_id uuid;
  v_mfg_id uuid;
  v_hsn_id uuid;
