  FOR org_rec IN SELECT id FROM public.organizations LOOP

    -- Item: 13525 - HEMFER FCM 500 10ML
    SELECT id INTO v_mfg_id FROM public.manufacturers WHERE organization_id = org_rec.id AND name = 'ALKEM';
    IF v_mfg_id IS NULL AND 'ALKEM' <> '' THEN
      INSERT INTO public.manufacturers (organization_id, name, code) VALUES (org_rec.id, 'ALKEM', UPPER(SUBSTRING(REGEXP_REPLACE('ALKEM', '[^A-Za-z0-9]', '', 'g') FROM 1 FOR 6))) RETURNING id INTO v_mfg_id;
    END IF;

    SELECT id INTO v_hsn_id FROM public.hsn_codes WHERE organization_id = org_rec.id AND code = '3004';

    INSERT INTO public.items (organization_id, code, name, packing, manufacturer_id, hsn_id, mrp, sale_rate, purchase_rate, is_active)
    VALUES (org_rec.id, '13525', 'HEMFER FCM 500 10ML', 'PCS', v_mfg_id, v_hsn_id, 1125, 857.14, 857.14, true)
    ON CONFLICT (organization_id, code) DO UPDATE
    SET name = EXCLUDED.name, packing = EXCLUDED.packing, manufacturer_id = EXCLUDED.manufacturer_id, hsn_id = EXCLUDED.hsn_id, mrp = EXCLUDED.mrp, sale_rate = EXCLUDED.sale_rate, purchase_rate = EXCLUDED.purchase_rate
    RETURNING id INTO v_item_id;

